  str_mail_detail_30003 = "คุณได้รับรางวัลสะสมอาหารที่ยังไม่ได้รับรอคุณอยู่! โปรดตรวจสอบโดยเร็วที่สุด!",
  str_mail_title_33200019 = "ปรับรางวัลสไปร์",
  str_mail_detail_33200019 = "เรียน เนวิเกเตอร์\nเราได้ปรับรางวัลการเคลียร์ครั้งที่ 1 ของระบบยอดแหลมในการอัปเดตวันที่ 6 กรกฎาคม\nความคืบหน้าของ Spire Challenge ก่อนการอัปเดตมีดังนี้:\nระดับน้ำ {1}, ไฟ: ระดับ {2}, ป่า: ระดับ {3}, ธันเดอร์: ระดับ {4}.\n\nจากรางวัลการเคลียร์ครั้งที่ 1 หลังจากการปรับเปลี่ยนและความคืบหน้าของความท้าทายในปัจจุบัน คุณจะได้รับรางวัลดังต่อไปนี้:\n(รางวัลการเคลียร์ครั้งที่ 1 ของ 4 Spiers จะออกพร้อมกัน)\n\nหากคุณมีคำถามใด ๆ โปรดติดต่อเราผ่านทางฝ่ายบริการลูกค้าอย่างเป็นทางการของเรา ขอบคุณที่สนับสนุน Alchemy Stars",
  str_mail_gm_season = "Eve",
  str_mail_title_season = "อีฟจัดสิ่งเหล่านี้มาให้คุณแล้ว!",
  str_mail_detail_season_1 = "เนวิเกเตอร์ คุณลืมอะไรไปรึเปล่า? ฉันสังเกตเห็นว่าบางรายการกำลังจะหมดอายุ ดังนั้นฉันจึงเปลี่ยนเป็นสิ่งที่มีประโยชน์ รายการเหล่านั้นควรอยู่ในโกดังของคุณแล้วในตอนนี้... อย่างไรก็ตาม นี่คือรายละเอียด อย่าลืมตรวจสอบ!\n\n{1} ×{2} ได้ถูกแลกเปลี่ยนเป็น {3} ×{4}",
  str_mail_detail_season_2 = "เนวิเกเตอร์ คุณลืมอะไรไปรึเปล่า? ฉันสังเกตเห็นว่าบางรายการกำลังจะหมดอายุ ดังนั้นฉันจึงเปลี่ยนเป็นสิ่งที่มีประโยชน์ รายการเหล่านั้นควรอยู่ในโกดังของคุณแล้วในตอนนี้... อย่างไรก็ตาม นี่คือรายละเอียด อย่าลืมตรวจสอบ!\n\n{3} ×{4} ได้ถูกแลกเปลี่ยนเป็น {5} ×{6}\n{1} ×{2} ได้ถูกแลกเปลี่ยนเป็น{7} ×{8}",
  str_mail_s2_gm_season = "อิริดอน",
  str_mail_s2_title_season = "โปรดอย่าลืมเรื่องเหล่านี้นะครับ/ค่ะ!",
  str_mail_s2_detail_season_1 = "เฮ้นาวิเกเตอร์ ขอบคุณมากที่ช่วยเสริมในฝันเรื่องนี้ ฉันได้เปลี่ยนบางสิ่งที่คุณอาจรู้สึกไม่สะดวกในการพกพาเป็นสิ่งที่มีประโยชน์มากขึ้น ซึ่งฉันได้เก็บไว้ในคลังของคุณ ข้อมูลด้านล่างนี้เป็นข้อมูลเพื่อให้คุณอ้างอิง\n\n{1}×{2} ถูกแลกเปลี่ยนเป็น {3}×{4}.",
  str_mail_s2_detail_season_2 = "สวัสดีคุณนาวิเกเตอร์ ขอบคุณมากที่ช่วยเสียสละในฝันเมื่อก่อนนะ ฉันได้เปลี่ยนแปลงของที่คุณอาจจะไม่สะดวกในการพกพาให้เป็นของที่มีประโยชน์มากขึ้น และเก็บไว้ในคลังของคุณ ข้อมูลด้านล่างนี้เป็นข้อมูลเพื่อให้คุณอ้างอิง\n\n{3}×{4} ถูกแลกเปลี่ยนเป็น {5}×{6}\n{1}×{2} ถูกแลกเปลี่ยนเป็น {7}×{8}",
