  str_mail_vote_detail_1 = "ฉันไม่เคยคาดหวังว่าจะได้รับการสนับสนุนที่แข็งแกร่งจากใคร... ขอบคุณนะ ผู้นำทาง ฉันจะยืนข้างๆคุณเช่นกันเป็นการตอบแทน",
  str_mail_vote_detail_2 = "ว้าว, คุณนาวิเกเตอร์ คุณทำทุกอย่างเพื่อให้ฉันมีชุดสวยๆใส่หรือเปล่า? โอ้ ฉันรู้สึกถึงความรู้สึกมากเลย ฉันจะทิ้งกระสุนน้ำมนต์สองสามนัดให้คุณทันทีนะ!",
  str_mail_vote_detail_3 = "มีอะไรดีกับชุดใหม่...? แต่ถ้ามันมาจากคุณ ฉันก็รู้สึกตื่นเต้นนะ... ฉันแค่อยากจะบอกว่า... ขอบคุณ.",
  str_mail_vote_detail_4 = "โอ้ว้า คุณพยายามเพื่อชุดใหม่ของฉันเหรอ? ไม่ต้องทำนะ! ขอให้สายลมยามบ่ายนำความขอบคุณของฉันไปถึงคุณ!",
  str_mail_vote_detail_5 = "ตอนเติบโตขึ้น ฉันไม่มีเสื้อผ้าที่เรียกว่าของตัวเองนอกจากชุดนักเรียนหลากหลายแบบ ขอบคุณที่ทำให้ฉันคิดถึงปัญหานี้ ผู้นำทาง",
  str_mail_vote_detail_6 = "ขอบคุณสำหรับความพากเพียรค่ะ ผู้นำทาง คุณทำให้ฉันรู้สึกว่าอาจเป็นเวลาที่จะปรับปรุงวิธีการแต่งกายของฉันแล้ว ฉันมองว่ามันเป็นประเภทของวินัย และฉันจะทำงานเพื่อรักษามัน",
  str_mail_vote_detail_7 = "เป็นเกียรติของฉันในฐานะชนชั้นสูงที่ได้รับการยอมรับและสนับสนุนจากคุณ ต้องยอมรับว่าฉันไม่ค่อยคุ้นเคยกับแฟชั่นล่าสุด คุณยินดีให้ความคิดเห็นของคุณบ้างไหม?",
  str_mail_vote_detail_8 = "ขอบคุณสำหรับความไว้วางใจและการสนับสนุน คุณไปโหวตให้คาร์ลีนหรือยัง? เธอทำงานหนักมาก ฉันหวังว่าคุณจะดูแลเธอด้วยนะ",
  str_mail_vote_detail_9 = "โอ้ นาวิเกเตอร์ที่ยิ่งใหญ่ ♪ ดูเหมือนคุณชอบเรามากจริงๆ ♪ แต่ถึงอย่างนั้น ♪ ก็ไม่หยุดริมผมของคุณจากการลดลง ♪",
  str_mail_vote_detail_10 = "ขอบคุณนะ คุณนาวิเกเตอร์ แต่คุณรู้ได้ไงว่าฉันไม่มีเงินซื้อเสื้อผ้า? ขอฉันเสนอซื้อกาแฟให้ครั้งหน้านะ ถ้าคุณไม่รังเกียจ...",
  str_mail_vote_detail_11 = "เอาล่ะ คุณได้ช่วยฉันอย่างไม่มีเงื่อนไขตลอดเวลา ฉันไม่รู้ว่าจะตอบแทนคุณยังไงดี... ฉันรู้แล้ว ฉันจะเล่นเพลงเฉพาะสำหรับคุณเมื่อไม่มีใครอยู่รอบ ๆ นั่นดีมั้ย?",
  str_mail_vote_detail_12 = "เฮ้ น่าสนใจนะ สำหรับฉัน ฉันก็อยากได้ชุดเสื้อผ้าสวย ๆ อีกชุดเสมอ ขอบคุณนะ โอ้ ฉันจะหาของขวัญแฟชั่นให้เธอด้วยเมื่อฉันมีโอกาสนะ",
  str_mail_vote_detail_13 = "ฉันสามารถรู้สึกถึงความไว้ใจจากคุณเมื่อคุณลงคะแนนเสียงให้ฉัน มันเป็นเพราะความรักหรือเปล่า นักเดินทางผู้กล้าหาญ?",
  str_mail_vote_detail_14 = "ใช่ค่ะ การสนับสนุนในเวลาที่เหมาะสมนั้นเหมือนกับการโจมตีในช่วงเวลาที่แม่นยำ ซึ่งต้องใช้ใจคิดที่แม่นยำและฉลาดอย่างที่คุณนาวิเกเตอร์มีอยู่ ขอบคุณค่ะ ฉันจะรักษาสิ่งนี้เสมอ",
  str_mail_vote_detail_15 = "พฟฟต์, นี่มันเขินจัง เลิกอ้อมค้อมแล้วบอกฉันสิว่าเธอต้องการอะไรจากฉัน... โอ้ว, นี่ก็เป็นเรื่องที่น่าประทับใจเชียว",
  str_mail_vote_detail_16 = "คุณกำลังพยายามทำให้ฉันมีความสุขใช่ไหม? งั้น คุณอยากให้ฉันใส่ชุดแบบไหนดี?",
  str_mail_vote_detail_17 = "คุณอยากให้ฉันได้โอกาสเหรอ? ขอบคุณนะ หลังจากที่ฉันชนะแล้ว มาฉลองด้วยแก้วไวน์สองแก้วกันเถอะ?",
  str_mail_vote_detail_18 = "ฉันชินกับการซ่อนตัวในเงามืดมานานแล้ว แต่ฉันก็ยังคบกับพวกเจ้าหนุ่มๆบ้างครั้ง ฉันแค่ไม่คาดหวังว่าจะได้รับการสนับสนุนเยอะขนาดนี้จากคุณ โอเค ฉันจะให้คุณนำหมากในเกมหมากรุกครั้งหน้า 3 ตานะ!",
  str_mail_vote_detail_19 = "ผมไม่สามารถเข้าใจความปิติและความคาดหวังของคุณได้ แต่ขอบคุณคุณอยู่ดี และเพื่อแสดงความยินดีตอบแทน คุณอยากจะพักผ่อนในลังไม้สีดำหรือเปล่า?",
  str_mail_vote_detail_20 = "ว้าว, มันจริงๆหรือที่มันเป็นของฉัน? แม้ว่าฉันจะถูกสาปแช่ง แต่ฉันก็ยังมีโชคบ้างเหมือนกับการได้รับการสนับสนุนที่ไม่สั่นสะเทือนจากคุณ, นาวิเกเตอร์ โปรดอนุญาตให้ฉันได้คิดถึงวิธีการขอบคุณคุณ...",
  str_mail_vote_detail_21 = "เอาเถอะ ฉันจะรับล่ะ แต่นี่ไม่ใช่การสูญเสียเงินเปล่าที่จะให้ชุดใหม่แก่ฉันหรือ? ถ้าฉันชนะ ก็ปรับให้มันเข้ากับโรบินได้นะ โบ๊ทสครับเปอร์",
  str_mail_vote_detail_22 = "คุณไม่จำเป็นต้องใช้ทรัพยากรให้ฉันเนวิเกเตอร์ ค่าใช้จ่ายเช่นการบำรุงรักษา Colossus และการรับรองลูกค้านั้นต้องใช้เงินเป็นจำนวนมาก แต่แม้กระนั้น ความคิดนี้ทำให้ฉันรู้สึกมีความสุขและรู้สึกถูกพระเจ้าอุปถัมภ์!",
  str_mail_vote_detail_23 = "ขอบคุณนะ! ชุดที่ทนทานและพอดีสำหรับการฝึกฝนนี่แหละที่จอมยุทธ์ต้องการ พูดถึงนั้น คุณจะมาฝึกฝนกับฉันเมื่อไหร่ล่ะ?",
  str_mail_vote_detail_24 = "อ้าว คุณก็คือเพื่อนที่ดีที่สุดของฉันจริง ๆ! ตู้เสื้อผ้าคอสตูมของเราเสมอๆ มันขาด \"ชิ้นสุดท้าย\" ที่จะทำให้มันสมบูรณ์ คุณกับฉันเข้ากันเป็นอย่างดี! ขอบคุณมากครับ!",
  str_mail_vote_detail_25 = "ฉันไม่คิดว่าคุณจะห่วงใยฉันขนาดนี้ ข้อเสนอนี้เป็นยังไง: คุณสามารถยืมชุดใหม่ที่ฉันได้มา แต่คุณต้องเป็นวิชาทดสอบของฉันเป็นตอบแทน นั่นเป็นความยุติธรรมใช่ไหม?",
  str_mail_vote_detail_26 = "ฉันโชคดีที่ได้รับความรักจากคุณ ชีวิตนั้นสั้น แต่ก็ไม่เป็นสิ่งที่เสียเปล่าหากเราหยุดเพื่อดมกลิ่นดอกกุหลาบ",
  str_mail_vote_detail_27 = "\"skin\" ที่ยอดเยี่ยมนี้ จะช่วยเพิ่มประสิทธิภาพในการเล่นเกมของฉันแน่นอน ฉันเดาว่าคุณนาวิเกเตอร์เข้าใจกันแล้วนะ! ขอบคุณมากครับ!",
  str_mail_vote_detail_28 = "ขอบคุณที่ชี้ทิศทางใหม่ให้ฉัน ฉันต้องไม่ยอมแพ้ไรน์ฮาร์ต อย่างน้อยเมื่อเป็นเรื่องของเสื้อผ้าที่เราครอบครอง!",
  str_mail_vote_detail_29 = "เครื่องแบบใหม่หรือ? นี่หมายความว่ามีสนามใหม่หรือ? แน่นอน ๆ คุณก็ลงคะแนนโหวตให้ฉันต่อไป! คุณจะได้รับผลตอบแทนอย่างโจรเมื่อทุกอย่างเสร็จสิ้น!",
  str_mail_vote_detail_30 = "แท้จริงแล้ว ฉันได้สะสมชุดสวย ๆ มากมายในระหว่างผจญภัยกับคุณ คุณผู้นำทาง และคุณยังคงสงวนโอกาสมีค่าให้ฉัน แม้ว่าฉันจะมีมากแล้ว? โอเค ฉันจะพยายามเก็บหนังสือเล่มนี้ให้คุณนะ!",
  str_mail_vote_detail_31 = "ฉันจะบอกคุณแค่นี้เท่านั้น เหมียว! ฉันรู้สึกถึงความรักของคุณให้ฉัน และนี่ทำให้ฉันมีความสุขมาก เหมียว! หลังจากที่ฉันลองใส่นี้ ไปนอนสักงีบใต้แสงอาทิตย์กันเถอะ เหมียว!",
  str_mail_vote_detail_32 = "ว้าว! นายเข้าใจจริงๆ! ชุดที่สวมใส่เหมาะสำหรับการต่อสู้!—เบนนี่\nฉันได้หนึ่งชุดด้วยเหรอ? การตัดสินใจที่ฉลาดและควรได้รับความชื่นชมจากฉัน—คุโระ",
  str_mail_vote_detail_33 = "การสนับสนุนของคุณได้ให้กำลังใจมากแก่ฉัน ซึ่งทำให้คุณเป็นมิตรสหายแห่งความยุติธรรมที่คู่ควร! หากคุณยินดี โปรดอนุญาตให้ฉันปักคำว่า \"ความยุติธรรม\" ลงบนเสื้อผ้าของคุณ!",
  str_mail_vote_detail_34 = "อะไรนะ? นี่แน่นอนว่าไม่ได้อยู่ในแผนเลย แต่ฉันก็ไม่เกลียดเลย งั้นเราก็ให้ชุดตัดเสื้อตามสั่งเป็นส่วนหนึ่งของแผนกันเถอะ ฉันจะทำงานหนักในส่วนนี้!",
  str_mail_vote_detail_35 = "เอ่อ, ฉันไม่ได้ขาดเสื้อผ้าที่นี่หรอกนะ, แต่เนื่องจากคุณโหวตให้ฉัน, ฉันควรลองใส่ดู... ไม่, อย่าเข้าใจผิด, ฉันไม่ได้รอคอยมันเลย!",
  str_mail_vote_detail_36 = "ฉันรู้ว่าคุณเลือกอะไร ดังนั้นขออนุญาตให้ฉันขอบคุณคุณ อย่างไรก็ตาม ถึงแม้ว่าเพชรจะสวยงาม สิ่งที่จับใจจริง ๆ คือความหมายของมัน ใช่ไหมครับ?",
  str_mail_vote_detail_37 = "ฉันไม่คิดว่าคุณจะโหวตให้ฉัน นาวิเกเตอร์ ชุดใหม่เหรอ? ความคิดนี้ทำให้ฉันตื่นเต้น ฉันคงสามารถใช้มันในการทำการสำรวจครั้งถัดไปได้.",
  str_mail_vote_detail_38 = "ว้าว ฉันชอบงานแบบนี้! นานแล้วที่ไม่ได้ซื้อชุดใหม่! ถ้าฉันชนะชุดแต่งกายใหม่ ต้องไปโชว์ให้ลูอิสและองค์ราชินีดูทันที!",
  str_mail_vote_detail_39 = "เป็นเรื่องน่าทึ่งที่ได้รับคะแนนเยอะๆ จากคุณ! ขอแสดงความขอบคุณด้วยการแสดงมายากลให้คุณดู! เอลฟ์ โปรดเตรียมกล่องขนมให้พร้อม!",
  str_mail_vote_detail_40 = "ชุดใหม่เหรอ? ฉันคิดว่าเข้าใจนะ! มันเหมือนการให้เครื่องมือและหุ่นยนต์ของฉันทาสีใหม่เป็นครั้งคราว ฮี, ฉันรอดูไม่ไหวว่าคุณมี \"สีทา\" อะไรให้ฉันบ้าง นาวิเกเตอร์",
  str_mail_vote_detail_41 = "เอาจริง ๆ แล้วฉันไม่ค่อยสนใจเรื่องนี้ แต่กระสุน คลิป และปลอกกระสุนทั้งหมดกำลังต้องการสกินใหม่ ดังนั้นขอให้ฉันขอบคุณแทนพวกเขาด้วยนะ",
  str_mail_vote_detail_42 = "เฮ้ย นี่ก็แปลกใหม่เนอะ! คุณรู้ไหมว่า ถ้าชอบฉันขนาดนี้ คุณก็สามารถเข้าร่วมกับเรดีเซล เวรนช์ได้เลยนะ! แล้วคุณก็ไม่ต้องโหวต ฉันยินดีให้กางเกงที่ขาฉันให้คุณเลย!",
  str_mail_vote_detail_43 = "คุณโหวตให้ฉันเหรอ? ฉันดีใจมากเลย! ฉันอยากโชว์ชุดใหม่ที่ได้รับให้พี่ชายและคุณผู้นำทางดูกันนะ",
  str_mail_vote_detail_44 = "อะไร, ได้คะแนนโหวตเยอะขนาดนี้เลยหรอ? ฉันควรขอบคุณยังไงดีนะ? ชุดใหม่... ถ้าเป็น Coolster ที่มีถุงมือ ฉันคงปรี้ดเลย!",
  str_mail_vote_detail_45 = "ชุดใหม่นี้ต้องเป็นชุดที่สวยงามอย่างพิเศษที่ออกแบบมาสำหรับดาราคนดัง... ฉันรอไม่ไหวแล้วที่จะขึ้นเวที! ดูจากจำนวนครั้งที่คุณโหวตให้ฉัน นี่คือตั๋ว VIP สำหรับคอนเสิร์ต!",
  str_mail_vote_detail_46 = "ความรักมากมายของเรดีเซลและหวานใจสุดฮอต! ไอดอลของคุณบาร์บาร่าก็เข้าร่วมในแข่งขันแล้ว! ฉันได้รับความกระตือรือร้นและการสนับสนุนจากคุณ! คุณจะได้รับรูปถ่ายที่ลงนามให้คุณในภายหลัง!",
  str_mail_vote_detail_47 = "ขอบคุณที่ชอบฉันนะ ถ้าเป็นไปได้ ฉันอยากให้อีฟได้ชุดใหม่ด้วย คุณจะโหวตให้เธอด้วยไหม?",
  str_mail_vote_detail_48 = "ไม่ว่าช่างเทคโนโลยีจะใส่อะไรก็ตาม แต่ฉันยังคงขอบคุณล่วงหน้านะ ผู้ชาย รั่วอีกแล้วหรอ...? ฉันจะติดตามคุณหลังจากฉันซ่อมมันเสร็จนะ",
  str_mail_vote_detail_49 = "ฉันต้องการชุดใหม่มานานแล้ว แต่คุณรู้ได้ยังไงล่ะ? คุณรอคอยให้ฉันสอบถามคุณในชุดนี้ใช่ไหม ผู้นำทาง?",
  str_mail_vote_detail_50 = "ใช่ ใช่ ทุกอย่างเป็นไปตามที่คาดหวัง แต่ก็ยังคงขอบคุณสำหรับการสนับสนุนของคุณ ทุกสิ่งนี้เป็นส่วนหนึ่งของแผนของ The Knowledge ฉันแน่ใจ",
  str_mail_vote_detail_51 = "โอ้ คุณโหวตให้ฉัน เยี่ยมเลย ฉันจะรอดูผลลัพธ์ แต่ถ้าฉันสังเกตเห็นการโกงเกิดขึ้น พวกเขาจะต้องตอบสนองต่อหนามของฉัน",
  str_mail_vote_detail_52 = "ผู้นำทาง แม้ว่าคุณจะโหวตให้ฉัน ฉันก็ยัง... ไม่, ถ้าคิดใหม่ คุณกำลังพยายามปกปิดคริสตัลบนฉันใช่ไหม? ฉันไม่เชื่อว่าฉันไม่สามารถเห็นเจตนาชั้นสูงของคุณ...",
  str_mail_vote_detail_53 = "คุณโหวตให้ฉันหรือยัง? หลงใหลในเสน่ห์ของฉันหรือเปล่า? ทำไมไม่มาดื่มกับฉันหลังจากนี้ล่ะ? แน่นอนว่าค่าเหล้าเธอจ่ายนะ",
  str_mail_vote_detail_54 = "ศรัทธาที่ยิ่งใหญ่คุ้มค่าพอที่จะสละทุกอย่างเพื่อมัน; ความสงบภายใน, สภาพจิตใจ, แม้กระทั่งชีวิตและจิตวิญญาณของเรา... ขอบคุณที่สนับสนุนฉัน ถ้าคุณร่วมมือกับเราจะดีมากขึ้น",
  str_mail_vote_detail_55 = "เพราะฉันต้องอยู่ในเกมเพราะคุณโหวตให้ฉันเหรอ? ไม่มีทางเลย ฉันต้องการชนะเฉพาะเมื่อคุณไม่โหวตให้ฉัน! รับทราบนะ? คะแนนโหวตของคุณทำให้ฉันมีความสุขเล็ก ๆ น้อย ๆ แต่เพียงเล็ก ๆ น้อย ๆ ดังนั้นอย่าคิดมากเกินไป!",
  str_mail_vote_detail_56 = "อย่านำฉันไปแข่งขันกับใคร ฉันชอบที่จะมีพื้นที่และความเงียบสงบของฉัน... รอสักครู่ ฉันไม่ได้บอกให้คุณไป แล้วก็ขอบคุณสำหรับการสนับสนุนของคุณ...",
  str_mail_vote_detail_57 = "ว้าว, ไม่คิดว่าคุณจะสนับสนุนฉันขนาดนี้ เดาว่าคุณปรับปรุงรสนิยมด้านเพลงของคุณแล้วใช่ไหม? งั้น, ขอฉันเล่นเพลงให้คุณฟังเป็นความขอบคุณอย่างแท้จริงนะ!",
  str_mail_vote_detail_58 = "ฉันขอบคุณการสนับสนุนของคุณที่ทำให้ฉันได้รับชื่อเรื่อง ขอบคุณครับ ฉันได้ปฏิเสธเกียรติความเป็นอย่างนี้มาก่อนเพราะฉันได้รับความสุขมานานแล้ว แต่เพื่อคุณและการทำภารกิจย้อนหลังกับบุคคลคนนั้น ฉันจะทำงานหนักต่อไป",
  str_mail_vote_detail_59 = "การเผาไหม้จะทำให้ความงามทั้งหมดกลายเป็นเถ้าถ่าน ดังนั้นคุณคาดหวังอะไร? ความคิดของคุณทำให้ฉันสับสน... แต่ฉันจะทำตามความคาดหวังของคุณเพื่อแสดงความยินดีที่คุณเลือกฉัน",
  str_mail_vote_detail_60 = "คุณต้องการให้ฉันมีโอกาสได้เสื้อผ้าใหม่? แลกกับการฉันจะเล่าเรื่องเก่าๆให้คุณฟัง... ใช่ มันไม่เกี่ยวข้องกับดาว แต่เกี่ยวกับเสื้อผ้าใหม่ของจักรพรรดิ",
  str_mail_vote_detail_61 = "คุณมีปัญหากับเครื่องแบบบางๆ ของฉันหรือเปล่า? ไม่ว่าฉันจะใส่อะไร ก็ไม่ได้ทำให้เสน่ห์และความยิ่งใหญ่ของฉันลดลง แต่คุณยังควรได้รับการชื่นชมที่โหวตให้คนที่ถูกต้อง",
  str_mail_vote_detail_62 = "ขอบคุณสำหรับท่าทางที่ดี ในเวลาที่ทุกอย่างมีอยู่ในความปรารถนาของธรรมชาติ คุณสนใจจะไปเดินเล่นในป่ากับฉันเพื่อสัมผัสความงามของธรรมชาติไหม",
  str_mail_vote_detail_63 = "คุณดูสนใจมากในการเปลี่ยนแปลงรูปลักษณ์ของฉัน ตั้งแต่คุณโหวต สัญลักษณ์ที่เรียกว่าความสุขได้ถูกเพิ่มเข้าไปในหน่วยความจำของฉัน มันรู้สึก... ยอดเยี่ยม.",
  str_mail_vote_detail_64 = "ความจริงที่คุณโหวตให้ฉันหลายครั้งแสดงว่าคุณชอบฉันมากใช่ไหม? ถ้ามีอารู้เรื่องนี้ เธออาจจะร้องไห้ด้วยความสุขนะ!",
  str_mail_vote_detail_65 = "นี่เป็นความคิดของเดย์นาหรือไม่? ไม่ใช่หรอ? ฉันคิดว่า... นี่คือวิธีที่คุณมองฉันสูงเหรอ? ฉันจะทำทุกอย่างที่สุดเพื่อไม่ทำให้คุณผิดหวัง...",
  str_mail_vote_detail_66 = "ฉันตกใจ ต้องมีออโรเรียนหลายร้อยคนบนยานโคลอสซัส แต่คุณกลับเลือกโหวตให้ฉัน ฉันจะตอบแทนการสนับสนุนของคุณเป็นสามเท่า",
  str_mail_vote_detail_67 = "ฉันดีใจที่เห็นคุณสบายดี หลังจากที่คุณใส่ใจในสิ่งที่ทหารผ่านศึกสวมใส่ ฉันยอมรับข้อเสนอและดูแลตัวเองด้วยนะครับ",
  str_mail_vote_detail_68 = "ฉันจะสวยขึ้นไหมนะ? ขอบคุณนะ ฉันไม่คาดคิดว่าจะมีวันนี้ และฉันมีความสุขมากเลย.",
  str_mail_vote_detail_69 = "ปกติแล้ว ผู้พิพากษามีรหัสแต่งกายของตนเอง แต่เนื่องจากคุณเชื่อว่ามีความจำเป็น ฉันจึงยินดีที่จะยอมรับ ฉันขอขอบคุณมาก ๆ และจนกว่าเราจะพบกันอีกครั้ง",
  str_mail_vote_detail_70 = "เฮ้เพื่อน แม้แต่ทหารรับจ้างยังรู้ว่าคุณโหวตให้ฉัน ฉันรู้สึกถึงความรู้สึกที่คุณไม่ลืมฉัน ไม่ว่าจะชนะหรือแพ้ ฉันยินดีที่จะดูดีขึ้นเพื่อคุณ",
  str_mail_vote_detail_71 = "ขอบคุณนะเพื่อน ฉันเห็นการถวายของมากมายในอัมบราตันและฉันไม่รู้สึกอะไรเลย คุณต้องการให้ฉันชนะครั้งนี้...? งั้น มันจะเป็นยังไงถ้าให้กิลด์ช่วยเหลือล่ะ?",
  str_mail_vote_detail_72 = "ฉันได้สลักความคิดและความเคารพของคุณลงบนน้ำแข็งของพระราชวังฤดูหนาว ฉันยินดีที่เห็นคุณยังคงสะอาดสบาย แม้ว่าคุณจะต้องผ่านความทุกข์สุขมากมาย ขอบคุณครับ",
  str_mail_vote_detail_73 = "ฉันเห็นว่าคุณโหวตให้ฉัน ฉันจริง ๆ ไม่คาดคิดว่าจะได้กระโดดบนเวทีในฐานะผู้จัดงาน... ขอบคุณนะ แต่ฉันก็กังวลว่าคุณจะสนุกกับงานเทศกาลหรือไม่",
  str_mail_vote_detail_74 = "ว้าว, มันเป็นความประหลาดใจที่ดีมาก! ฉันได้ต้องการเสมอที่จะเป็นส่วนหนึ่งของงานเช่นนี้ แต่งตัวอย่างเรียบร้อยและสนุกกับการอยู่ในสายตาของทุกคน! สัญญาว่าคุณจะขึ้นเวทีกับฉัน!",
  str_mail_vote_detail_75 = "คุณเกี่ยวข้องกับการสมรู้ร่วมคิดใดๆ หรือไม่ หรือคุณถูกกำหนดให้สนับสนุน Ascended อย่างฉัน? คุณไม่จำเป็นต้องบอกฉัน! การรวบรวมการสนับสนุนในการต่อสู้กับสิ่งที่ไม่ทราบเป็นสิ่งที่จำเป็น ขอบคุณ!",
  str_mail_vote_detail_76 = "คุณอยากเห็นฉันใส่อะไรนอกจากชุดนี้หรือ? ถ้านั่นคือความต้องการของคุณ ฉันยินดีที่จะปฏิบัติตาม ด้วยความยินดีของฉัน คราวหน้าฉันจะซื้อรอบให้คุณ ไม่ต้องกังวล ฉันจะสั่งอะไรที่ปกติๆ นะ",
  str_mail_vote_detail_77 = "ขอเทิดทูนรัตติกาลสีขาว! นี่คือสำหรับฉันใช่ไหม? ค่ะ ฉันเห็นว่าฉันต้องพยายามเพื่อตอบสนองความคาดหวังของคุณ ขอบคุณ เคเลสไทต์คนสุดท้าย อย่าลืมบำรุงร่างกายและดื่มน้ำเพิ่มเติมนะคะ.",
  str_mail_vote_detail_78 = "เฮ้ คาเลสไทต์น้อย โหวตนี้คือสำหรับฉันใช่ไหม? ฮูม... รูบี้ดูเหมือนจะไม่อยู่ที่นี่ แล้วฉันต้องถูกแน่ๆ ขอบคุณนะ! แต่ด้วยการที่คุณชูชื่นฉัน ฉันต้องชนะตอนนี้ใช่ไหม?!",
  str_mail_vote_detail_79 = "ไม่ใช่ผู้นำทางเหรอ! ฉันไม่ได้มีชุดที่ดีในระยะเวลาที่ยาวนาน ไม่ว่าผลลัพธ์จะเป็นอย่างไร ฉันยินดีกับความคิดนี้มากเลย!",
  str_mail_vote_detail_80 = "เมื่อไหร่ผู้นำทางที่ขี้อายนี้กล้าขึ้นเนี่ย? ดังนั้นคุณอยากเห็นฉันใส่ชุดที่คุณต้องการใช่ไหม? ไม่ต้องกังวล ฉันจะชนะมันให้คุณ.",
  str_mail_vote_detail_81 = "ฉันมีชุดเพียงพอแล้วนะเด็ก! และฉันยังทำลายเครื่องแบบอยู่... แต่ก็ขอบคุณนะเด็ก ในการตอบแทนคุณ ฉันจะทำการตัดเย็บโปรแกรมการฝึกฝนใหม่เฉพาะสำหรับคุณ",
  str_mail_vote_detail_82 = "จอมทัพคือต้นแบบของอิลลูมินา และคุณต้องการให้ฉันเปลี่ยนเป็นอย่างอื่น? ฉันทำให้คุณลำบาก? ไม่เป็นไร ฉันไม่สามารถสงสัยในความประสงค์ดีของเพื่อนร่วมทีมได้ ดังนั้นขอบคุณ! ฉันจะชนะในการแข่งขันนี้",
  str_mail_vote_detail_83 = "ต้องการให้ Axelia ดูสวยขึ้นหรือ? แต่ฉันมีแสงสว่างอยู่แล้ว ฉันจะทิ้งค impressions อย่างไรในชุดที่แตกต่างกันนะ? ฮูมม, ฉันไม่แน่ใจ แต่ฉันรู้ว่าฉันต้องขอบคุณคุณ",
  str_mail_vote_detail_84 = "โอ้ ขอบคุณสำหรับการสนับสนุนนะ! ชุดใหม่จะช่วยลดจำนวนครั้งที่ฉันต้องกลับมายานโคลอสซัสในชุดที่เปื้อนเลือด! ขอโทษนะ หวังว่าฉันไม่ได้ทำให้คุณรู้สึกขยะแขยงเมื่อมีเหตุการณ์นั้นเกิดขึ้น.",
